<?php defined('ABSPATH') || exit; global $wpdb; $user = wp_get_current_user(); ?>
<div class="tj-container"><div class="tj-candidate-heading"><div><span class="tj-eyebrow"><?php tj_e('KHÔNG GIAN CỦA BẠN', 'YOUR WORKSPACE'); ?></span><h1><?php tj_e('Xin chào,', 'Hello,'); ?> <?php echo esc_html($user->display_name); ?></h1><p class="tj-muted"><?php tj_e('Theo dõi cơ hội và chuẩn bị cho cuộc phỏng vấn tiếp theo.', 'Track opportunities and prepare for your next interview.'); ?></p></div></div><nav class="tj-tabs"><?php foreach (['' => tj_t('Tổng quan', 'Overview'), 'ho-so' => tj_t('Hồ sơ & CV', 'Profile & CV'), 'ung-tuyen' => tj_t('Đã ứng tuyển', 'Applications'), 'da-luu' => tj_t('Đã lưu', 'Saved jobs'), 'lich-phong-van' => tj_t('Lịch phỏng vấn', 'Interviews'), 'thong-bao' => tj_t('Thông báo', 'Notifications')] as $path => $label) { ?><a class="<?php echo $section === $path ? 'active' : ''; ?>" href="<?php echo esc_url(tj_url('tai-khoan' . ($path ? '/' . $path : ''))); ?>"><?php echo esc_html($label); ?></a><?php } ?></nav>
<?php if ($section === 'ho-so') { ?><div class="tj-detail-grid"><section class="tj-panel"><h2><?php tj_e('Thông tin cá nhân', 'Personal information'); ?></h2><?php tj_form_start('profile', 'tj-stack'); tj_input('full_name', tj_t('Họ và tên', 'Full name'), $user->display_name, 'text', true); tj_input('email', 'Email', $user->user_email, 'email', true); tj_input('phone', tj_t('Điện thoại', 'Phone'), get_user_meta($user->ID, 'tj_phone', true), 'tel', true); tj_button(); ?></form></section><section class="tj-panel"><h2><?php tj_e('CV của bạn', 'Your CVs'); ?></h2><p class="tj-muted"><?php tj_e('CV chỉ được bạn và quản trị viên truy cập.', 'CVs are only accessible to you and the administrator.'); ?></p><?php tj_form_start('upload_cv', 'tj-stack', true); tj_input('cv', 'PDF / DOC / DOCX · ≤5 MB', '', 'file', true); tj_button('Tải CV lên', 'Upload CV'); ?></form><ul class="tj-file-list"><?php foreach (tj_rows('files', 50, $user->ID) as $file) { ?><li><a href="<?php echo esc_url(tj_url('tai-cv/' . $file['id'])); ?>"><?php echo esc_html($file['original_name']); ?> ↓</a><small><?php echo esc_html(tj_date($file['created_at'])); ?></small></li><?php } ?></ul></section></div>
<?php } elseif ($section === 'ung-tuyen') { if (!empty($_GET['application'])) { tj_application_detail(absint($_GET['application']), false); } else { tj_application_list(false); } }
elseif ($section === 'da-luu') { $saved = tj_jobs(['saved_user' => $user->ID, 'pg' => absint($_GET['pg'] ?? 1)], true); echo '<div class="tj-stack">'; foreach ($saved['posts'] as $job) { tj_job_card($job); } if (!$saved['posts']) { tj_empty(tj_t('Chưa lưu việc làm nào.', 'No saved jobs yet.')); } echo '</div>'; tj_pagination((int)$saved['pages']); }
elseif ($section === 'lich-phong-van') { tj_interview_list(false); }
elseif ($section === 'thong-bao') { tj_notifications(); }
else {
    $apps = (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM ' . tj_table('applications') . ' WHERE user_id=%d', $user->ID));
    $saved = (int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM ' . tj_table('saved') . ' WHERE user_id=%d', $user->ID));
    ?><div class="tj-summary-grid"><?php foreach ([[$apps, tj_t('Hồ sơ đã gửi', 'Applications sent')], [$saved, tj_t('Việc làm đã lưu', 'Saved jobs')], [tj_unread(), tj_t('Thông báo chưa đọc', 'Unread notifications')]] as [$count, $label]) { ?><div class="tj-panel"><span class="tj-muted"><?php echo esc_html($label); ?></span><strong class="tj-stat"><?php echo (int)$count; ?></strong></div><?php } ?></div><?php if (!get_user_meta($user->ID, 'tj_phone', true)) { ?><div class="tracking-card"><h3><?php tj_e('Hoàn thiện hồ sơ để sẵn sàng ứng tuyển', 'Complete your profile to start applying'); ?></h3><a href="<?php echo esc_url(tj_url('tai-khoan/ho-so')); ?>"><?php tj_e('Cập nhật thông tin và CV', 'Update profile and CV'); ?> →</a></div><?php } ?><section class="tj-panel"><h2><?php tj_e('Hồ sơ gần đây', 'Recent applications'); ?></h2><?php tj_application_list(false); ?></section><?php } ?></div>
